```tsx
import React, { useState } from 'react';
import { EyeIcon, EyeOffIcon } from 'lucide-react';

export interface LoginFormData {
  email: string;
  password: string;
}

export interface ValidationError {
  field: 'email' | 'password';
  message: string;
}

export type FormStatus = 'idle' | 'submitting' | 'success' | 'error';

export interface LoginFormProps {
  onSubmit: (data: LoginFormData) => void;
  formStatus: FormStatus;
  error: string | null;
}

const LoginForm: React.FC<LoginFormProps> = ({
  onSubmit,
  formStatus,
  error,
}) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const validatePassword = (password: string): boolean => {
    return password.length >= 6;
  };

  const isEmailValid = email && validateEmail(email);
  const isPasswordValid = password && validatePassword(password);

  const isValid = isEmailValid && isPasswordValid;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isValid) {
      setEmailError(isEmailValid ? '' : 'Please enter a valid email.');
      setPasswordError(isPasswordValid ? '' : 'Password must be at least 6 characters long.');
      return;
    }
    onSubmit({ email, password });
  };

  return (
    <div className="w-full max-w-md p-8 space-y-6 bg-white rounded-xl shadow-md border border-gray-100">
      <h1 className="text-2xl font-bold text-center text-gray-800">Login</h1>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
            Email
          </label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => {
              setEmail(e.target.value);
              setEmailError('');
            }}
            className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent focus:border-transparent transition-all ${
              emailError ? 'border-red-300 bg-red-50' : 'border-gray-300 hover:border-gray-400'
            }`}
            placeholder="you@example.com"
          />
          {emailError && (
            <p className="mt-1 text-sm text-red-600 flex items-center gap-1">
              <span className="text-red-500">⚠️</span>
              {emailError}
            </p>
          )}
        </div>

        <div>
          <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
            Password
          </label>
          <div className="relative">
            <input
              id="password"
              type={showPassword ? 'text' : 'password'}
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                setPasswordError('');
              }}
              className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent focus:border-transparent transition-all ${
                passwordError ? 'border-red-300 bg-red-50' : 'border-gray-300 hover:border-gray-400'
              }`}
              placeholder="Enter your password"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute inset-y-0 right-0 px-3 flex items-center text-gray-500 hover:text-gray-700"
            >
              {showPassword ? <EyeOffIcon size={18} /> : <EyeIcon size={18} />}
            </button>
          </div>
          {passwordError && (
            <p className="mt-1 text-sm text-red-600 flex items-center gap-1">
              <span className="text-red-500">⚠️</span>
              {passwordError}
            </p>
          )}
        </div>

        <button
          type="submit"
          disabled={!isValid}
          className={`w-full py-3 rounded-lg font-medium text-white transition-all transform hover:scale-[1.01] ${
            isValid
              ? 'bg-accent hover:bg-purple-600 active:scale-95'
              : 'bg-gray-300 cursor-not-allowed'
          }`}
        >
          {formStatus === 'submitting' ? 'Signing in...' : 'Sign In'}
        </button>
      </form>

      {error && (
        <div className="text-sm text-red-600 text-center mt-4">
          <span className="text-red-500">⚠️</span> {error}
        </div>
      )}
    </div>
  );
};

export { LoginForm };
```
